// Rango de fechas segun el periodo pedido ('hoy', 'semana', 'mes' o 'mes anterior').
const consulta = $('Datos de la consulta').first().json ?? {};

// El periodo puede venir dado ('semana') o deducirse de la pregunta que ha hecho
// la tienda: asi el bot responde a "¿cuánto se recaudó esta semana?" con la semana.
// "Este mes" es el mes en curso (del dia 1 a hoy); el anterior hay que pedirlo
// ("el mes pasado", "el mes anterior").
const texto = String(consulta.texto ?? '').toLowerCase();
let periodo = String(consulta.periodo ?? '').toLowerCase();
if (!periodo) {
  if (texto.includes('hoy') || texto.includes('este dia') || texto.includes('hoy dia')) periodo = 'hoy';
  else if (texto.includes('semana')) periodo = 'semana';
  else if (texto.includes('mes pasado') || texto.includes('mes anterior')) periodo = 'mes anterior';
  else periodo = 'mes';
}

// Hoy en Madrid, como el resto de flujos: en UTC, de madrugada, seria todavia ayer.
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());
const [anio, mes, dia] = hoy.split('-').map(Number);
const iso = (d) => d.toISOString().slice(0, 10);
const inicio = new Date(Date.UTC(anio, mes - 1, dia));

let desde = hoy;
let hasta = hoy;

if (periodo === 'hoy') {
  // ya esta
} else if (periodo === 'semana') {
  desde = iso(new Date(inicio.getTime() - 6 * 86400000));
} else if (periodo === 'mes anterior') {
  desde = iso(new Date(Date.UTC(anio, mes - 2, 1)));
  hasta = iso(new Date(Date.UTC(anio, mes - 1, 0)));
} else {
  // mes en curso, hasta hoy
  periodo = 'mes';
  desde = iso(new Date(Date.UTC(anio, mes - 1, 1)));
}

return [{ json: { periodo, desde, hasta } }];

// Cifras del negocio, tal cual las devuelve la API.
//
// - Recaudacion del periodo: ventas directas + abonos cobrados.
// - Pendiente de cobro: lo que falta de todos los apartados activos.
// - Apartados que vencen este mes natural.
// Ninguna cifra se inventa: aqui solo se suman.
const rango = $('Calcular el rango').first().json ?? {};

const lista = (nodo) => $('nodo').all
  ? []
  : [];

const ventas = $('Ventas del periodo').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((v) => v && v.id !== undefined);
const abonos = $('Abonos del periodo').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((a) => a && a.id !== undefined);
const apartados = $('Apartados').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((a) => a && a.id !== undefined);

const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';

const totalVentas = redondear(ventas.reduce((s, v) => s + Number(v.importe ?? 0), 0));
const totalAbonos = redondear(abonos.reduce((s, a) => s + Number(a.importe ?? 0), 0));
const pendientes = apartados.filter((a) => String(a.estado) === 'activo');
const pendienteTotal = redondear(pendientes.reduce((s, a) => s + Number(a.pendiente ?? 0), 0));

const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());
const [anio, mes] = hoy.split('-').map(Number);
const mesActual = hoy.slice(0, 7);

const vencenEsteMes = apartados.filter((a) => {
  if (String(a.estado) !== 'activo') return false;
  const limite = String(a.fecha_limite ?? '');
  return limite.slice(0, 7) === mesActual;
});

return [{
  json: {
    periodo: rango.periodo,
    desde: rango.desde,
    hasta: rango.hasta,
    ventas_directas: totalVentas,
    abonos: totalAbonos,
    recaudacion: redondear(totalVentas + totalAbonos),
    pendiente_cobro: pendienteTotal,
    num_ventas: ventas.length,
    num_abonos: abonos.length,
    apartados_activos: pendientes.length,
    vencen_este_mes: vencenEsteMes.map((a) => ({
      id: a.id,
      cliente: a.cliente,
      producto: a.producto,
      pendiente: a.pendiente,
      fecha_limite: a.fecha_limite,
    })),
    cifras_texto: [
      'Recaudado del ' + rango.desde + ' al ' + rango.hasta + ': ' + euros(totalVentas + totalAbonos),
      'Pendiente de cobro: ' + euros(pendienteTotal),
    ],
  },
}];
